/**
 * The keyboard help section that describes how to interact with a HeaterCoolerNode.
 *
 * @author Jesse Greenberg (PhET Interactive Simulations)
 */

import { string_scenery_phet_keyboardHelpDialog_heatCoolOff_StringProperty } from '../../strings/keyboardHelpDialog/heatCoolOff.js';
import { string_scenery_phet_keyboardHelpDialog_heatCoolControls_StringProperty } from '../../strings/keyboardHelpDialog/heatCoolControls.js';
import { string_scenery_phet_keyboardHelpDialog_maximumHeat_StringProperty } from '../../strings/keyboardHelpDialog/maximumHeat.js';
import { string_scenery_phet_keyboardHelpDialog_maximumCool_StringProperty } from '../../strings/keyboardHelpDialog/maximumCool.js';
import '../../../../globals.js';
import optionize, { EmptySelfOptions } from '../../../../phet-core/js/optionize.js';
import sceneryPhet from '../../sceneryPhet.js';
import NumberKeyNode from '../NumberKeyNode.js';
import KeyboardHelpSectionRow from './KeyboardHelpSectionRow.js';
import SliderControlsKeyboardHelpSection, { ArrowKeyIconDisplay, SliderControlsKeyboardHelpSectionOptions } from './SliderControlsKeyboardHelpSection.js';

type SelfOptions = EmptySelfOptions;
type ParentOptions = SliderControlsKeyboardHelpSectionOptions;
export type HeatCoolControlsKeyboardHelpSectionOptions = SelfOptions & ParentOptions;

export default class HeatCoolControlsKeyboardHelpSection extends SliderControlsKeyboardHelpSection {
  public constructor( providedOptions?: HeatCoolControlsKeyboardHelpSectionOptions ) {

    const offIcon = new NumberKeyNode( 0 );
    const offStringRow = KeyboardHelpSectionRow.labelWithIcon( string_scenery_phet_keyboardHelpDialog_heatCoolOff_StringProperty, offIcon );

    const options = optionize<HeatCoolControlsKeyboardHelpSectionOptions, SelfOptions, ParentOptions>()( {
      arrowKeyIconDisplay: ArrowKeyIconDisplay.UP_DOWN,

      headingStringProperty: string_scenery_phet_keyboardHelpDialog_heatCoolControls_StringProperty,
      jumpToMaximumStringProperty: string_scenery_phet_keyboardHelpDialog_maximumHeat_StringProperty,
      jumpToMinimumStringProperty: string_scenery_phet_keyboardHelpDialog_maximumCool_StringProperty,

      additionalRows: [
        offStringRow
      ]
    }, providedOptions );

    super( options );
  }
}

sceneryPhet.register( 'HeatCoolControlsKeyboardHelpSection', HeatCoolControlsKeyboardHelpSection );